 private SoundAudioInput(File file){snapshot=file;}
 public static SoundAudioInput create(Context c)throws IOException{File dir=new File(c.getCacheDir(),"one-sound");if(!dir.isDirectory()&&!dir.mkdirs())throw new IOException("음성 저장 공간");return new SoundAudioInput(new File(dir,"sound-"+UUID.randomUUID()+".input"));}
