 /** Explicit five-second foreground capture; samples never become an audio file. */
 public void microphone(Context c,SoundMath.Cancel cancel,Runnable progress)throws Exception{
  sourceType="MICROPHONE";sourceRate=16000;sourceChannels=1;AudioRecord recorder=null;long started=SystemClock.elapsedRealtime();float[] values=new float[80000];int count=0;MessageDigest digest=MessageDigest.getInstance("SHA-256");
  try{SoundMath.check(cancel);if(c.checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)!=android.content.pm.PackageManager.PERMISSION_GRANTED)throw new SecurityException("microphone permission");int minimum=AudioRecord.getMinBufferSize(16000,AudioFormat.CHANNEL_IN_MONO,AudioFormat.ENCODING_PCM_16BIT);if(minimum<1||minimum>64000)throw new IOException("마이크 형식을 확인하세요");recorder=new AudioRecord(MediaRecorder.AudioSource.VOICE_RECOGNITION,16000,AudioFormat.CHANNEL_IN_MONO,AudioFormat.ENCODING_PCM_16BIT,Math.min(64000,Math.max(16000,minimum*2)));microphoneClosed=false;if(recorder.getState()!=AudioRecord.STATE_INITIALIZED)throw new IOException("마이크를 열 수 없습니다");recorder.startRecording();if(recorder.getRecordingState()!=AudioRecord.RECORDSTATE_RECORDING)throw new IOException("마이크를 시작할 수 없습니다");if(progress!=null)progress.run();long lastProgress=SystemClock.elapsedRealtime(),until=lastProgress+5000;byte[] block=new byte[3200];while(count<values.length&&SystemClock.elapsedRealtime()<until){SoundMath.check(cancel);int n=recorder.read(block,0,Math.min(block.length,(values.length-count)*2),AudioRecord.READ_NON_BLOCKING);if(n<0)throw new IOException("마이크 읽기");if(n==0){Thread.sleep(10);continue;}if((n&1)!=0)throw new IOException("PCM alignment");digest.update(block,0,n);sourceBytes+=n;if(SystemClock.elapsedRealtime()-lastProgress>=500){lastProgress=SystemClock.elapsedRealtime();if(progress!=null)progress.run();}for(int i=0;i<n;i+=2)values[count++]=(short)((block[i]&255)|((block[i+1]&255)<<8))/32768f;}SoundMath.check(cancel);if(count<1600)throw new IOException("소리를 다시 녹음하세요");pcm=Arrays.copyOf(values,count);sourcePcm=pcm;sourceSha256=SoundMath.hex(digest.digest());pcmSha256=SoundMath.pcmSha(pcm);prepareMs=SystemClock.elapsedRealtime()-started;
  }finally{try{if(recorder!=null){try{if(recorder.getRecordingState()==AudioRecord.RECORDSTATE_RECORDING)recorder.stop();}finally{recorder.release();microphoneClosed=true;}}}finally{sourceClosed=microphoneClosed;}}
 }
 private static int u16(RandomAccessFile f)throws IOException{return f.readUnsignedByte()|(f.readUnsignedByte()<<8);}
 private static long u32(RandomAccessFile f)throws IOException{return Integer.toUnsignedLong(Integer.reverseBytes(f.readInt()));}
 private float[] wave(SoundMath.Cancel cancel)throws Exception{
  try(RandomAccessFile file=new RandomAccessFile(snapshot,"r")){if(file.readInt()!=0x52494646)return null;u32(file);if(file.readInt()!=0x57415645)return null;int format=0,bits=0,align=0;long dataOffset=-1,dataBytes=0;
   while(file.getFilePointer()+8<=file.length()){SoundMath.check(cancel);int chunk=file.readInt();long length=u32(file),offset=file.getFilePointer();if(length>file.length()-offset)throw new IOException("WAV 길이를 확인하세요");if(chunk==0x666d7420){if(length<16)throw new IOException("WAV 형식");format=u16(file);sourceChannels=u16(file);long rate=u32(file);if(rate>192000)throw new IOException("음성 샘플 속도");sourceRate=(int)rate;u32(file);align=u16(file);bits=u16(file);}else if(chunk==0x64617461){dataOffset=offset;dataBytes=length;}file.seek(offset+length+(length&1));}
   if(format!=1&&format!=3)return null;if(dataOffset<0||sourceChannels<1||sourceChannels>8||sourceRate<4000||align!=sourceChannels*(bits/8)||dataBytes%align!=0||(format==3&&bits!=32)||(format==1&&bits!=16&&bits!=24&&bits!=32))throw new IOException("지원되는 PCM WAV를 선택하세요");long frames=dataBytes/align;if(frames<1||frames>(long)sourceRate*SoundMath.MAX_SECONDS)throw new IOException("30초 이하 음성을 선택하세요");float[] samples=new float[(int)frames];file.seek(dataOffset);
   for(int i=0;i<samples.length;i++){if((i&2047)==0)SoundMath.check(cancel);double sum=0;for(int ch=0;ch<sourceChannels;ch++){float value;if(format==3)value=Float.intBitsToFloat(Integer.reverseBytes(file.readInt()));else if(bits==16)value=(short)u16(file)/32768f;else if(bits==24){int v=file.readUnsignedByte()|(file.readUnsignedByte()<<8)|(file.readUnsignedByte()<<16);if((v&0x800000)!=0)v|=0xff000000;value=v/8388608f;}else value=Integer.reverseBytes(file.readInt())/2147483648f;if(!Float.isFinite(value))throw new IOException("PCM 값");sum+=value;}samples[i]=(float)Math.max(-1,Math.min(1,sum/sourceChannels));}return samples;
  }
 }
 private float[] codec(SoundMath.Cancel cancel)throws Exception{
  MediaExtractor extractor=new MediaExtractor();MediaCodec decoder=null;extractorReleased=false;long deadline=SystemClock.elapsedRealtime()+45000;List<float[]> blocks=new ArrayList<>();int total=0;
  try{extractor.setDataSource(snapshot.getAbsolutePath());int track=-1;MediaFormat format=null;String mime="";for(int i=0;i<extractor.getTrackCount();i++){MediaFormat candidate=extractor.getTrackFormat(i);String type=candidate.getString(MediaFormat.KEY_MIME);if(type!=null&&type.startsWith("audio/")){track=i;format=candidate;mime=type;break;}}if(track<0)throw new IOException("음성 트랙을 확인하세요");if(format.containsKey(MediaFormat.KEY_DURATION)&&format.getLong(MediaFormat.KEY_DURATION)>30000000L)throw new IOException("30초 이하 음성을 선택하세요");extractor.selectTrack(track);sourceRate=format.getInteger(MediaFormat.KEY_SAMPLE_RATE);sourceChannels=format.getInteger(MediaFormat.KEY_CHANNEL_COUNT);decoder=MediaCodec.createDecoderByType(mime);decoderReleased=false;decoder.configure(format,null,null,0);decoder.start();MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();boolean inputDone=false,outputDone=false;int encoding=AudioFormat.ENCODING_PCM_16BIT;
   while(!outputDone){SoundMath.check(cancel);if(SystemClock.elapsedRealtime()>deadline)throw new IOException("음성 디코딩 시간이 초과되었습니다");if(!inputDone){int index=decoder.dequeueInputBuffer(10000);if(index>=0){ByteBuffer input=decoder.getInputBuffer(index);if(input==null)throw new IOException("음성 디코더");int n=extractor.readSampleData(input,0);if(n<0){decoder.queueInputBuffer(index,0,0,0,MediaCodec.BUFFER_FLAG_END_OF_STREAM);inputDone=true;}else{decoder.queueInputBuffer(index,0,n,extractor.getSampleTime(),0);extractor.advance();}}}int index=decoder.dequeueOutputBuffer(info,10000);if(index==MediaCodec.INFO_OUTPUT_FORMAT_CHANGED){MediaFormat next=decoder.getOutputFormat();int rate=next.getInteger(MediaFormat.KEY_SAMPLE_RATE),channels=next.getInteger(MediaFormat.KEY_CHANNEL_COUNT);if(total>0&&(rate!=sourceRate||channels!=sourceChannels))throw new IOException("가변 PCM 형식을 확인하세요");sourceRate=rate;sourceChannels=channels;if(next.containsKey(MediaFormat.KEY_PCM_ENCODING))encoding=next.getInteger(MediaFormat.KEY_PCM_ENCODING);}
    else if(index>=0){try{if(sourceRate<4000||sourceRate>192000||sourceChannels<1||sourceChannels>8)throw new IOException("음성 PCM 형식");ByteBuffer output=decoder.getOutputBuffer(index);if(output==null)throw new IOException("음성 디코더 출력");int bytes=encoding==AudioFormat.ENCODING_PCM_FLOAT?4:encoding==AudioFormat.ENCODING_PCM_16BIT?2:0;if(bytes==0||info.size%(bytes*sourceChannels)!=0)throw new IOException("PCM 형식을 확인하세요");output.position(info.offset);output.limit(info.offset+info.size);output.order(ByteOrder.LITTLE_ENDIAN);int frames=info.size/(bytes*sourceChannels);if((long)total+frames>(long)sourceRate*30)throw new IOException("30초 이하 음성을 선택하세요");float[] block=new float[frames];for(int i=0;i<frames;i++){double sum=0;for(int ch=0;ch<sourceChannels;ch++){float sample=bytes==4?output.getFloat():output.getShort()/32768f;if(!Float.isFinite(sample))throw new IOException("PCM 값");sum+=sample;}block[i]=(float)Math.max(-1,Math.min(1,sum/sourceChannels));}blocks.add(block);total+=frames;outputDone=(info.flags&MediaCodec.BUFFER_FLAG_END_OF_STREAM)!=0;}finally{decoder.releaseOutputBuffer(index,false);}}
   }if(total<1)throw new IOException("소리가 담긴 파일을 선택하세요");float[] samples=new float[total];int offset=0;for(float[] b:blocks){System.arraycopy(b,0,samples,offset,b.length);offset+=b.length;}return samples;
  }finally{try{if(decoder!=null){try{decoder.stop();}finally{decoder.release();decoderReleased=true;}}}finally{extractor.release();extractorReleased=true;}}
 }
 public JSONObject json()throws Exception{return new JSONObject().put("sourceSha256",sourceSha256).put("pcmSha256",pcmSha256).put("sourceType",sourceType).put("sourceBytes",sourceBytes).put("sourceRate",sourceRate).put("sourceChannels",sourceChannels).put("sampleRate",16000).put("sampleCount",pcm==null?0:pcm.length).put("durationSec",pcm==null?0:pcm.length/16000d).put("prepareMs",prepareMs).put("decodeMs",decodeMs).put("sourceClosed",sourceClosed).put("microphoneClosed",microphoneClosed).put("audioClosed",sourceClosed&&microphoneClosed&&decoderReleased&&extractorReleased).put("rawAudioStored",snapshot.isFile()).put("transcriptStored",false).put("decoderReleased",decoderReleased).put("extractorReleased",extractorReleased).put("temporaryInputDeleted",tempDeleted);}
